    // Cumplimiento general
    addPage();pdfHeader(doc,8,'CUMPLIMIENTO DE LEAD TIME - GENERAL',period);const rowsG=[];for(const territory of ['LOCAL','NACIONAL']){const src=territory==='LOCAL'?s.local:s.national;const yesT=src.filter(r=>r.complies==='SI').length,noT=src.length-yesT;rowsG.push([territory,int(yesT),pctText(pct(yesT,src.length)),int(noT),pctText(pct(noT,src.length)),int(src.length)]);for(const type of ['EXP','REG']){const g=src.filter(r=>r.type===type);if(!g.length)continue;const yes=g.filter(r=>r.complies==='SI').length;rowsG.push([`  ${type}`,int(yes),pctText(pct(yes,g.length)),int(g.length-yes),pctText(pct(g.length-yes,g.length)),int(g.length)]);}}rowsG.push(['TOTAL',int(s.yes),pctText(s.comp),int(s.late),pctText(pct(s.late,s.total)),int(s.total)]);pdfTable(doc,10,48,[45,30,36,30,36,30],['TERRITORIO','DENTRO','% DENTRO','FUERA','% FUERA','TOTAL'],rowsG,{rowH:11,fontSize:9.4,headerFontSize:8.5});doc.setFillColor(239,245,255);doc.roundedRect(224,52,64,78,4,4,'F');doc.setTextColor(13,54,135);doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text('CUMPLIMIENTO',256,69,{align:'center'});doc.text('GENERAL',256,77,{align:'center'});doc.setFontSize(30);doc.text(pctText(s.comp),256,98,{align:'center'});doc.setFontSize(9);doc.setTextColor(60,70,85);const compLines=doc.splitTextToSize(`${int(s.yes)} servicios dentro del plazo de ${int(s.total)} atendidos`,52);compLines.forEach((line,i)=>doc.text(line,256,112+i*5,{align:'center'}));
    // diario general
    addPage();pdfHeader(doc,9,'CONSOLIDADO DE SERVICIOS DIARIOS',period);const dailyTotal=s.daily.days.map((d,i)=>s.daily.local[i]+s.daily.national[i]);const yGen=dailyServicesTable(doc,10,44,215,s.daily.days,dailyTotal,{pairs:5,month:a.month});doc.addImage(dailyChart(s.daily.days,s.daily.local,s.daily.national,'BOTH'),'PNG',10,yGen+3,216,72);doc.setFillColor(245,248,255);doc.roundedRect(232,46,55,119,4,4,'F');doc.setFont('helvetica','bold');doc.setTextColor(13,54,135);doc.setFontSize(10);doc.text('PICO DEL MES',259.5,61,{align:'center'});doc.setFontSize(22);doc.text(String(s.daily.maxAny),259.5,76,{align:'center'});doc.setFontSize(7.5);doc.text(`servicios el ${s.daily.maxAnyDay} de ${String(a.period||'').toLowerCase()}`,259.5,86,{align:'center',maxWidth:48});doc.setFontSize(9.2);doc.text('PROMEDIO DIARIO',259.5,103,{align:'center'});doc.text('LOCAL',259.5,111,{align:'center'});doc.setFontSize(18);doc.text(String(s.daily.avgL),259.5,124,{align:'center'});doc.setFontSize(9.2);doc.text('PROMEDIO DIARIO',259.5,141,{align:'center'});doc.text('NACIONAL',259.5,149,{align:'center'});doc.setFontSize(18);doc.text(String(s.daily.avgN),259.5,160,{align:'center'});doc.setFontSize(11);doc.text(`PROMEDIO GENERAL DIARIO: ${s.daily.avgGeneral}`,12,178);
